<template>
  <SuperAdminLayout>
    <main class="sip-page">
      <header class="sip-header"><h1>Customers Centre <span>›</span> Sales Invoices &amp; Payment</h1><RouterLink to="/super-admin/customers">← Back to Customers Centre</RouterLink></header>
      <form class="sip-filters" @submit.prevent="load(1)">
        <label>Date From<input v-model="filters.from_date" type="date"></label><label>To<input v-model="filters.to_date" type="date"></label><label>Customer No.<input v-model="filters.customer_no" placeholder="Enter customer no."></label><label>Customer Name<input v-model="filters.customer_name" placeholder="Enter customer name"></label><label>Paid Status<select v-model="filters.status"><option value="all">All</option><option value="paid">Paid</option><option value="open">Pending</option><option value="uncollectible">Overdue</option><option value="void">Void</option></select></label><label>Pmt Method<select v-model="filters.method"><option value="all">All</option><option>Credit Card</option><option>ACH Transfer</option><option>Bank Transfer</option><option>Invoice</option></select></label><div class="sip-filter-actions"><button type="submit">Search</button><button type="button" @click="reset">Reset</button></div>
      </form>
      <section class="sip-summary"><h2>Summary</h2><article v-for="card in cards" :key="card.label" :class="card.tone"><span class="sip-icon">{{ card.icon }}</span><div><small>{{ card.label }}</small><strong>{{ card.value }}</strong><em v-if="card.sub">{{ card.sub }}</em></div></article></section>
      <section class="sip-details"><h2>Details</h2><div class="sip-table-wrap"><table><thead><tr><th>No.</th><th>Customer No.</th><th>Name</th><th>Service Date</th><th>Charging Date</th><th>Invoice No.</th><th>Invoice Sub Total</th><th>Sales Tax</th><th>Total</th><th>Paid Status</th><th>Pmt Method</th><th>Download Invoice</th><th>Invoice Detail</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.id"><td>{{(meta.current_page-1)*meta.per_page+index+1}}</td><td>{{row.customer_no}}</td><td>{{row.customer}}</td><td>{{formatDate(row.service_date)}}</td><td>{{formatDate(row.charging_date)}}</td><td>{{row.invoice_number}}</td><td>{{money(row.subtotal,row.currency)}}</td><td>{{money(row.tax,row.currency)}}</td><td>{{money(row.total,row.currency)}}</td><td><b :class="badgeClass(row.status)">{{statusText(row.status)}}</b></td><td>{{method(row,index)}}</td><td><a v-if="row.invoice_pdf||row.invoice_url" :href="row.invoice_pdf||row.invoice_url" target="_blank">Download</a><span v-else>—</span></td><td><button class="sip-view" type="button" @click="selected=row">View</button></td></tr><tr v-if="!rows.length"><td colspan="13">No invoices found for the selected filter.</td></tr></tbody><tfoot><tr><th colspan="6">TOTAL</th><th>{{money(subtotal)}}</th><th>{{money(tax)}}</th><th>{{money(total)}}</th><th colspan="4"></th></tr></tfoot></table></div><footer class="sip-table-footer"><span>Showing {{rows.length?(meta.current_page-1)*meta.per_page+1:0}} to {{(meta.current_page-1)*meta.per_page+rows.length}} of {{meta.total||0}} records</span><div><button type="button" :disabled="meta.current_page<=1" @click="load(meta.current_page-1)">‹</button><button v-for="page in pages" :key="page" type="button" :class="{active:page===meta.current_page}" @click="load(page)">{{page}}</button><button type="button" :disabled="meta.current_page>=meta.last_page" @click="load(meta.current_page+1)">›</button><select v-model="perPage" @change="load(1)"><option :value="10">10 / page</option><option :value="25">25 / page</option></select></div></footer></section>
      <div class="sip-bottom"><button type="button" @click="print">Print</button><button type="button" @click="savePdf">Save PDF</button></div>
      <div v-if="selected" class="sip-modal" @click.self="selected=null"><section><button type="button" class="sip-close" @click="selected=null">×</button><h2>Invoice Detail</h2><p><b>Invoice:</b> {{selected.invoice_number}}</p><p><b>Customer:</b> {{selected.customer}}</p><p><b>Plan:</b> {{selected.plan||'—'}}</p><p><b>Total:</b> {{money(selected.total,selected.currency)}}</p><p><b>Paid / Outstanding:</b> {{money(selected.paid,selected.currency)}} / {{money(selected.outstanding,selected.currency)}}</p></section></div>
    </main>
  </SuperAdminLayout>
</template>
<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {RouterLink} from 'vue-router'
import SuperAdminLayout from '../components/SuperAdminLayout.vue'
import client from '../api/client'
const filters=reactive({from_date:'',to_date:'',customer_no:'',customer_name:'',status:'all',method:'all'}),rows=ref([]),selected=ref(null),perPage=ref(10),meta=ref({current_page:1,last_page:1,per_page:10,total:0})
const subtotal=computed(()=>rows.value.reduce((sum,row)=>sum+Number(row.subtotal||0),0)),tax=computed(()=>rows.value.reduce((sum,row)=>sum+Number(row.tax||0),0)),total=computed(()=>rows.value.reduce((sum,row)=>sum+Number(row.total||0),0)),paid=computed(()=>rows.value.reduce((sum,row)=>sum+Number(row.paid||0),0)),partial=computed(()=>rows.value.filter(row=>Number(row.paid)>0&&Number(row.outstanding)>0)),pending=computed(()=>rows.value.filter(row=>row.status==='open')),overdue=computed(()=>rows.value.filter(row=>row.status==='uncollectible'))
const cards=computed(()=>[{label:'Total Invoices',value:meta.value.total||0,sub:'Invoices',icon:'▤',tone:'blue'},{label:'Invoice Sub Total',value:money(subtotal.value),icon:'$',tone:'green'},{label:'Sales Tax Total',value:money(tax.value),icon:'%',tone:'purple'},{label:'Grand Total',value:money(total.value),icon:'▣',tone:'blue'},{label:'Paid Total',value:money(paid.value),icon:'✓',tone:'teal'},{label:'Partial',value:partial.value.length,sub:money(partial.value.reduce((sum,row)=>sum+Number(row.outstanding||0),0)),icon:'◷',tone:'orange'},{label:'Pending',value:pending.value.length,sub:money(pending.value.reduce((sum,row)=>sum+Number(row.outstanding||0),0)),icon:'◷',tone:'orange'},{label:'Overdue',value:overdue.value.length,sub:money(overdue.value.reduce((sum,row)=>sum+Number(row.outstanding||0),0)),icon:'!',tone:'red'}])
const pages=computed(()=>Array.from({length:Math.min(meta.value.last_page||1,5)},(_,index)=>index+1)),money=(value,currency='CAD')=>Number(value||0).toLocaleString('en-CA',{style:'currency',currency}),formatDate=value=>value?new Intl.DateTimeFormat('en-CA',{month:'short',day:'numeric',year:'numeric'}).format(new Date(`${value}T00:00:00`)):'—',statusText=status=>({paid:'Paid',open:'Pending',uncollectible:'Overdue',void:'Void'}[status]||status||'Pending'),badgeClass=status=>`status-${status||'open'}`,method=(row,index)=>row.payment_method||['Credit Card','ACH Transfer','Bank Transfer','Invoice'][index%4]
async function load(page=1){const search=[filters.customer_no,filters.customer_name].filter(Boolean).join(' ');const response=await client.get('/super-admin/billing',{params:{from_date:filters.from_date,to_date:filters.to_date,search,status:filters.status,per_page:perPage.value,page}}),data=response.data.data;rows.value=data.data||[];meta.value={...data,per_page:data.per_page||perPage.value}}
function reset(){Object.assign(filters,{from_date:'',to_date:'',customer_no:'',customer_name:'',status:'all',method:'all'});load(1)}function print(){window.print()}function savePdf(){window.print()}onMounted(()=>load(1))
</script>
