:#0648d8;font-size:1rem}.sip-table-wrap{overflow:auto}.sip-details table{width:100%;min-width:1370px;border-collapse:collapse;font-size:.73rem}.sip-details th,.sip-details td{border:1px solid #e2e9f1;padding:10px 9px;text-align:center;white-space:nowrap}.sip-details th{background:#f4f6f9;font-size:.68rem}.sip-details td:nth-child(3){text-align:left}.sip-details a,.sip-view{border:0;background:none;color:#0050e7;text-decoration:none;font-weight:700;cursor:pointer}.sip-details b{display:inline-block;border-radius:4px;padding:4px 9px;font-size:.7rem;font-weight:500}.status-paid{background:#e2f7e6;color:#147634}.status-open{background:#fff3d7;color:#e07b00}.status-uncollectible{background:#ffe3e3;color:#e42020}.status-void{background:#eef1f5;color:#536276}.sip-details tfoot th{color:#071541;background:#fafbfd}.sip-table-footer{display:flex;align-items:center;justify-content:space-between;padding:14px 8px;font-size:.75rem}.sip-table-footer div{display:flex;align-items:center;gap:9px}.sip-table-footer button{width:34px;height:34px;border:1px solid #d3dfed;border-radius:4px;background:#fff;color:#071541}.sip-table-footer button.active{background:#0849d9;color:#fff;border-color:#0849d9}.sip-bottom{display:flex;gap:20px;margin-top:28px}.sip-bottom button{height:40px;min-width:164px;font-size:.9rem}.sip-modal{position:fixed;inset:0;z-index:50;display:grid;place-items:center;background:#0008}.sip-modal section{position:relative;min-width:340px;border-radius:8px;background:#fff;padding:24px;box-shadow:0 8px 24px #0004}.sip-modal h2{margin-top:0;color:#0749d6}.sip-close{position:absolute;right:10px;top:7px;border:0;background:none;font-size:1.5rem;cursor:pointer}@media(max-width:1180px){.sip-filters{grid-template-columns:repeat(3,1fr)}.sip-summary{grid-template-columns:repeat(4,1fr)}}@media(max-width:700px){.sip-header{align-items:flex-start;gap:12px}.sip-header h1{font-size:1.35rem}.sip-filters,.sip-summary{grid-template-columns:repeat(2,1fr)}.sip-table-footer{align-items:flex-start;gap:10px;flex-direction:column}}@media print{.sip-header a,.sip-filters,.sip-table-footer,.sip-bottom,.sip-modal{display:none!important}.sip-page{margin:0}.sip-summary{grid-template-columns:repeat(4,1fr)}}
.sip-details thead th{background:linear-gradient(90deg,#06245d,#1058c7)!important;color:#fff!important;border-color:#a8c6f4!important;font-size:.76rem}.sip-details tfoot th{background:#fff!important;color:#071541!important}.sip-table-footer{background:#fff!important;border-top:1px solid #e2e9f1}
</style>
